  INPUT TERMID    AT 8 ,68  LEN 6   PROT COLOR=CYAN
  FIELD           AT 8 ,56  LEN 11  PROT COLOR=GREEN        "Terminal. :"
  INPUT CONDATE   AT 9 ,68  LEN 6   PROT COLOR=CYAN
  FIELD           AT 9 ,56  LEN 11  PROT COLOR=GREEN        "Connected :"
  INPUT CONTIME   AT 10,68  LEN 6   PROT COLOR=CYAN

  FIELD           AT 12,56  LEN 16  PROT COLOR=GREEN        "Available Frames"
