MAP MAINMENUTICK SIZE 24x80
  INPUT CURDATE   AT 6 ,68  LEN 6   PROT COLOR=CYAN
  INPUT CURTIME   AT 7 ,68  LEN 6   PROT COLOR=CYAN
ENDMAP * MAINMENUTICK

MAP MAINMENUHELP1 SIZE 24x80
  FIELD           AT 0 ,0   LEN 17  PROT BRIGHT COLOR=BLUE  "FSPF - Fake SPF -"
  FIELD           AT 0 ,18  LEN 15  PROT BRIGHT COLOR=RED   "HELP!"

  FIELD           AT 2 ,0   LEN 78   PROT COLOR=BLUE          "FSPF is a simple little menu program, with aspirations!"
  FIELD           AT 3 ,0   LEN 78   PROT COLOR=BLUE          "Aspirations for being helpful, making your life better, in some small way."

  FIELD           AT 5 ,0   LEN 78   PROT COLOR=BLUE          "In an effort to accomplish this goal, FSPF presents you with Frames."
  FIELD           AT 6 ,0   LEN 78   PROT COLOR=BLUE          "Frames kinda look like Panes, but simpler, like FSPF."
  FIELD           AT 7 ,0   LEN 78   PROT COLOR=BLUE          "Each frame is a collection of Links, to Transaction IDs, or to other Frames."
  
  FIELD           AT 9 ,0   LEN 78   PROT COLOR=BLUE          "With the Option line you can enter:                              Example"
  FIELD           AT 10,0   LEN 78   PROT COLOR=BLUE          "* '/TID' to LINK to the given Transaction ID with arguments.       /HELP"
  FIELD           AT 11,0   LEN 78   PROT COLOR=BLUE          "* '@FRAME' to jump directly to a Frame.                            @DEMO"
  FIELD           AT 12,0   LEN 78   PROT COLOR=BLUE          "* '?TOPIC' to jump the Help page TOPIC . Works on all Frames.      ?ISPF"
  FIELD           AT 13,0   LEN 78   PROT COLOR=BLUE          "* 'Link ID' to execute the link.                                      DU"
  FIELD           AT 14,0   LEN 78   PROT COLOR=BLUE          "* 'Frame ID' to jump to the Frame.                                     A"
  FIELD           AT 15,0   LEN 78   PROT COLOR=BLUE          "* 'Frame ID.Link ID' to use a Link in a different Frame.            D.RH"
  FIELD           AT 16,0   LEN 78   PROT COLOR=BLUE          "* A Frame name, Including 'MAIN', to jump to the Frame.             DEMO"
  FIELD           AT 17,0   LEN 78   PROT COLOR=BLUE          "* 'Q' to quit.  Works on all Frames.                                   Q"
  FIELD           AT 18,0   LEN 78   PROT COLOR=BLUE          "* Anything else is treated as a Transaction ID                      WZEN"
  
  FIELD           AT 20,0   LEN 78   PROT COLOR=BLUE          "Arguments to a Transaction ID are passed in via DFHCOMMAREA."
  
  FIELD           AT 23,0   LEN 78   PROT COLOR=BLUE          "Press ENTER to exit."

  CURSOR          AT 23,0
ENDMAP * MAINMENUHELP1

MAP MAINMENUHELP2 SIZE 24x80
  FIELD           AT 0 ,17  LEN 50  PROT COLOR=BLUE         "Welcome to BRICKS Transaction Server"
  FIELD           AT 1 ,17  LEN 50  PROT COLOR=WHITE        "This message changes with the Frame."
  FIELD           AT 0 ,1   LEN 5   PROT BRIGHT COLOR=RED   "HELP!"
  FIELD           AT 0 ,73   LEN 5   PROT BRIGHT COLOR=RED   "HELP!"

  FIELD           AT 4 ,68  LEN 5   PROT UNDERSCORE COLOR=BLUE "MAIN"
  STOP            AT 4 ,74
  FIELD           AT 4 ,56  LEN 6   PROT COLOR=GREEN        "Frame . . :"
  FIELD           AT 5 ,68  LEN 10  PROT COLOR=CYAN         "admin"
  FIELD           AT 5 ,56  LEN 11  PROT COLOR=GREEN        "User ID . :"
  FIELD           AT 6 ,68  LEN 6   PROT COLOR=CYAN         "2026-06-18"
  FIELD           AT 6 ,56  LEN 11  PROT COLOR=GREEN        "Date. . . :"
  FIELD           AT 7 ,68  LEN 6   PROT COLOR=CYAN         "14:15:16"
  FIELD           AT 7 ,56  LEN 11  PROT COLOR=GREEN        "Time. . . :"
  FIELD           AT 8 ,68  LEN 6   PROT COLOR=CYAN         "T0003 - M2"
  FIELD           AT 8 ,56  LEN 11  PROT COLOR=GREEN        "Terminal. :"
  FIELD           AT 9 ,68  LEN 6   PROT COLOR=CYAN         "2026-06-18"
  FIELD           AT 9 ,56  LEN 11  PROT COLOR=GREEN        "Connected :"
  FIELD           AT 10,68  LEN 6   PROT COLOR=CYAN         "12:34:56"

  FIELD           AT 12,56  LEN 16  PROT COLOR=GREEN        "Available Frames"
  FIELD           AT 12,76  LEN 2   PROT COLOR=CYAN         "ID"

  FIELD           AT 2 ,0   LEN 10  PROT                    "Option ==>"
  FIELD           AT 2 ,11  LEN 40  UNDERSCORE COLOR=CYAN   " Enter a Link ID, Command, Frame ID ..."
  STOP            AT 2 ,52

  FIELD           AT 18,0   LEN 2   PROT COLOR=WHITE        "I"
  FIELD           AT 19,0   LEN 2   PROT COLOR=WHITE        "D"
  FIELD           AT 20,0   LEN 2   PROT COLOR=WHITE        "R"
  FIELD           AT 18,3   LEN 5   PROT COLOR=YELLOW       "ISPF"
  FIELD           AT 19,3   LEN 5   PROT COLOR=CYAN         "DEMO"
  FIELD           AT 20,3   LEN 5   PROT COLOR=PINK         "?CEDA"
  FIELD           AT 18,10  LEN 42  PROT COLOR=BLUE         "ISPF Source Editor"
  FIELD           AT 19,10  LEN 42  PROT COLOR=BLUE         "More Demos..."
  FIELD           AT 20,10  LEN 42  PROT COLOR=BLUE         "CEDA - Resource Manager Help"

  FIELD           AT 13,56  LEN 20  PROT COLOR=BLUE         "Main Menu"
  FIELD           AT 14,56  LEN 20  PROT COLOR=CYAN         "Bricks Demos"
  FIELD           AT 15,56  LEN 20  PROT COLOR=PINK         "Help"
  FIELD           AT 16,56  LEN 20  PROT COLOR=RED          "Administration"
  FIELD           AT 13,77  LEN 1   PROT COLOR=WHITE        "M"
  FIELD           AT 14,77  LEN 1   PROT COLOR=WHITE        "D"
  FIELD           AT 15,77  LEN 1   PROT COLOR=WHITE        "H"
  FIELD           AT 16,77  LEN 1   PROT COLOR=WHITE        "A"

  FIELD           AT 4 ,0   LEN 44  PROT COLOR=WHITE        "Welcome to FSPF, the little menu that tries."
  FIELD           AT 5 ,0   LEN 49  PROT COLOR=WHITE        "Here is what all this stuff on your screen means."

  FIELD           AT 7 ,2   LEN 52  PROT COLOR=CYAN         "To the right is some information about your session."
  FIELD           AT 8 ,34  LEN 20  PROT COLOR=CYAN         "Note the Frame name."
  FIELD           AT 9 ,13  LEN 41  PROT COLOR=CYAN         "You can always get to a frame with @NAME."
  
  FIELD           AT 12,19  LEN 35  PROT COLOR=WHITE        "This is a list of available frames."
  FIELD           AT 13,36  LEN 18  PROT COLOR=WHITE        "Just enter the ID."

  FIELD           AT 15,0   LEN 18  PROT COLOR=CYAN         "These are links. They are what FSPF is all about."
  FIELD           AT 16,0   LEN 18  PROT COLOR=CYAN         "A Link can be a Transaction, Frame, or Help Screen."
  FIELD           AT 17,0   LEN 18  PROT COLOR=CYAN         "Just enter the ID in the Option field above."

  FIELD           AT 21,0   LEN 18  PROT COLOR=CYAN         "You can also enter the Transaction ID in Option above."
  
  FIELD           AT 18,60   LEN 18  PROT COLOR=YELLOW       "This space "
  FIELD           AT 19,60   LEN 18  PROT COLOR=YELLOW       "intentionally"
  FIELD           AT 20,60   LEN 18  PROT COLOR=YELLOW       "left blank."

  FIELD           AT 23,0   LEN 78  PROT COLOR=BLUE         "PF1=Help  PF2=Edit  PF3=Back  PF5=Reload  PF6=Recall  PF7/8=Up/Down  PF12=Exit"
  CURSOR          AT 23,0
ENDMAP * MAINMENUHELP2

