MAP EDITLINKHELP1 SIZE 24x80
  FIELD           AT 0 ,0   LEN 20  PROT BRIGHT COLOR=BLUE  "FSPF - Link Editor -"
  FIELD           AT 0 ,21  LEN 18  PROT BRIGHT COLOR=RED   "HELP!"
  FIELD           AT 1 ,0   LEN 78  PROT COLOR=BLUE         "D to Duplicate / P to Purge / ENTER=COMMIT"

  FIELD           AT 2 ,0   LEN 1   PROT COLOR=CYAN         "A D ID C  Order  Frame S Trans C  Description                                C"

  INPUT ACTN2     AT 3 ,0   LEN 1   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT COMMF2    AT 3 ,2   LEN 2   PROT            COLOR=GREEN  DEFAULT ""
  INPUT ID2       AT 3 ,4   LEN 2   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT IDC2      AT 3 ,7   LEN 1   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT ORDER2    AT 3 ,11  LEN 4   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT FRAME2    AT 3 ,17  LEN 5   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT SUBM2     AT 3 ,23  LEN 1   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT TRANS2    AT 3 ,25  LEN 5   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT TRANSC2   AT 3 ,31  LEN 1   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT DESCR2    AT 3 ,34  LEN 42  PROT UNDERSCORE COLOR=GREEN  DEFAULT ""
  INPUT DESCRC2   AT 3 ,77  LEN 1   PROT UNDERSCORE COLOR=GREEN  DEFAULT ""

  STOP            AT 3 ,9
  STOP            AT 3 ,33
  STOP            AT 3 ,79

  FIELD           AT 5 ,0   LEN 78   PROT COLOR=BLUE          "Column definitions:"
  FIELD           AT 6 ,0   LEN 6    PROT COLOR=CYAN          "A"
  FIELD           AT 6 ,6   LEN 70   PROT COLOR=BLUE          "- Perform an action on the Link. D to duplicate, P to purge/delete."
  FIELD           AT 7 ,0   LEN 6    PROT COLOR=CYAN          "D"
  FIELD           AT 7 ,6   LEN 70   PROT COLOR=BLUE          "- If this column contains a C then there is a value set for DFHCOMMAREA."
  FIELD           AT 8 ,0   LEN 6    PROT COLOR=CYAN          "ID"
  FIELD           AT 8 ,6   LEN 70   PROT COLOR=BLUE          "- What the user types into the Option input line for the Link."
  FIELD           AT 9 ,0   LEN 6    PROT COLOR=CYAN          "C"
  FIELD           AT 9 ,6   LEN 70   PROT COLOR=BLUE          "- Color to render the ID in."
  FIELD           AT 10,0   LEN 6    PROT COLOR=CYAN          "Order"
  FIELD           AT 10,6   LEN 70   PROT COLOR=BLUE          "- The relative order the place the Link on the page."
  FIELD           AT 10,70  LEN 8    PROT COLOR=YELLOW        "REQUIRED"
  FIELD           AT 11,0   LEN 6    PROT COLOR=CYAN          "Fram"
  FIELD           AT 11,6   LEN 70   PROT COLOR=BLUE          "- The Frame this Link belongs to. MAIN is the default."
  FIELD           AT 11,70  LEN 8    PROT COLOR=YELLOW        "REQUIRED"
  FIELD           AT 12,0   LEN 6    PROT COLOR=CYAN          "S"
  FIELD           AT 12,6   LEN 70   PROT COLOR=BLUE          "- Submenu. The Transaction ID is actually a Frame to switch to."
  FIELD           AT 13,0   LEN 6    PROT COLOR=CYAN          "Trans"
  FIELD           AT 13,6   LEN 70   PROT COLOR=BLUE          "- The Transaction ID to LINK to when the user enters the ID."
  FIELD           AT 14,0   LEN 6    PROT COLOR=CYAN          "C"
  FIELD           AT 14,6   LEN 70   PROT COLOR=BLUE          "- The color to render the Transaction ID in."
  FIELD           AT 15,0   LEN 6    PROT COLOR=CYAN          "Descr"
  FIELD           AT 15,6   LEN 70   PROT COLOR=BLUE          "- The description for the Link."
  FIELD           AT 16,0   LEN 6    PROT COLOR=CYAN          "C"
  FIELD           AT 16,6   LEN 70   PROT COLOR=BLUE          "- The color to render the description in."

  FIELD           AT 18,0   LEN 6    PROT COLOR=CYAN          "PF5"
  FIELD           AT 18,6   LEN 70   PROT COLOR=BLUE          "- Reload without saving."
  FIELD           AT 18,40  LEN 6    PROT COLOR=CYAN          "ENTER"
  FIELD           AT 18,46  LEN 30   PROT COLOR=BLUE          "- Commit changes."
  FIELD           AT 19,0   LEN 6    PROT COLOR=CYAN          "PF4"
  FIELD           AT 19,6   LEN 70   PROT COLOR=BLUE          "- Edit the Frames."
  FIELD           AT 19,40  LEN 6    PROT COLOR=CYAN          "PF6"
  FIELD           AT 19,46  LEN 30   PROT COLOR=BLUE          "- Filter on a Frame."
  FIELD           AT 20,0   LEN 6    PROT COLOR=CYAN          "PF2"
  FIELD           AT 20,6   LEN 70   PROT COLOR=BLUE          "- Edit the DFHCOMMAREA value set when LINKing a Transaction ID."

  FIELD           AT 22,0   LEN 78   PROT COLOR=BLUE          "Records must be unique by their ID, Order and Frame."

  FIELD           AT 23,0   LEN 78   PROT COLOR=BLUE          "Press ENTER to continue to the next page."

  CURSOR          AT 23,0
ENDMAP * EDITLINKHELP1

