  FIELD           AT 6 ,1   LEN 1    PROT COLOR=YELLOW        "\"
  FIELD           AT 6 ,4   LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 6 ,7   LEN 1    PROT COLOR=RED           "\ \"
  FIELD           AT 6 ,15  LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 6 ,20  LEN 1    PROT COLOR=CYAN          "\"
