  FIELD           AT 7 ,21  LEN 1    PROT COLOR=CYAN          "\"
  FIELD           AT 7 ,25  LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 7 ,32  LEN 1    PROT COLOR=WHITE         "==> The Transaction ID to LINK to and color."

  FIELD           AT 8 ,3   LEN 1    PROT COLOR=YELLOW        "\"
  FIELD           AT 8 ,6   LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 8 ,9   LEN 1    PROT COLOR=RED           "\ \"
  FIELD           AT 8 ,17  LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 8 ,22  LEN 1    PROT COLOR=CYAN          "\"
