MAP EDITFRAMEHELP1 SIZE 24x80
  FIELD           AT 0 ,0   LEN 21  PROT BRIGHT COLOR=BLUE    "FSPF - Frame Editor -"
  FIELD           AT 0 ,22  LEN 18  PROT BRIGHT COLOR=RED     "HELP!"
  FIELD           AT 1 ,0   LEN 78  PROT COLOR=BLUE           "D to Duplicate / P to Purge / ENTER=COMMIT"
  FIELD           AT 1 ,71  LEN 7   PROT COLOR=WHITE          "Rows: 2"

  FIELD           AT 2 ,0   LEN 1   PROT COLOR=CYAN           "A  ID C  Order  Name  Description          C  Welcome Message                C"

  INPUT ACTN1     AT 3 ,0   LEN 1   UNDERSCORE COLOR=YELLOW
  INPUT ID1       AT 3 ,3   LEN 2   UNDERSCORE COLOR=GREEN
  INPUT IDC1      AT 3 ,6   LEN 1   UNDERSCORE COLOR=GREEN
  INPUT ORDER1    AT 3 ,10  LEN 4   NUMERIC UNDERSCORE COLOR=GREEN
  INPUT NAME1     AT 3 ,16  LEN 5   UNDERSCORE COLOR=GREEN
  INPUT DESCR1    AT 3 ,22  LEN 20  UNDERSCORE COLOR=GREEN
  INPUT DESCRC1   AT 3 ,43  LEN 1   UNDERSCORE COLOR=GREEN
  INPUT WELCOM1   AT 3 ,46  LEN 30  UNDERSCORE COLOR=GREEN
  INPUT WELCOMC1  AT 3 ,77  LEN 1   UNDERSCORE COLOR=GREEN

  STOP            AT 3 ,2
  STOP            AT 3 ,8
  STOP            AT 3 ,15
  STOP            AT 3 ,21
  STOP            AT 3 ,45
  STOP            AT 3 ,79

  FIELD           AT 5 ,0   LEN 78   PROT COLOR=BLUE          "Column definitions:"
  FIELD           AT 6 ,0   LEN 8    PROT COLOR=CYAN          "A"
  FIELD           AT 6 ,8   LEN 70   PROT COLOR=BLUE          "- Perform an action on the Frame. D to duplicate, P to purge/delete."
  FIELD           AT 7 ,0   LEN 8    PROT COLOR=CYAN          "ID"
  FIELD           AT 7 ,8   LEN 70   PROT COLOR=BLUE          "- What the user types into the Option input line for the Frame."
  FIELD           AT 8 ,0   LEN 8    PROT COLOR=CYAN          "C"
  FIELD           AT 8 ,8   LEN 70   PROT COLOR=BLUE          "- Color to render the ID in."
  FIELD           AT 9 ,0   LEN 8    PROT COLOR=CYAN          "Order"
  FIELD           AT 9 ,8   LEN 70   PROT COLOR=BLUE          "- The relative order the place the Frame on the list."
  FIELD           AT 10,0   LEN 8    PROT COLOR=CYAN          "Name"
  FIELD           AT 10,8   LEN 70   PROT COLOR=BLUE          "- The name for this Frame from Links and in the top right."
  FIELD           AT 10,70  LEN 8    PROT COLOR=YELLOW        "REQUIRED"
  FIELD           AT 11,0   LEN 8    PROT COLOR=CYAN          "C"
  FIELD           AT 11,8   LEN 70   PROT COLOR=BLUE          "- Color to render the Name in the top right."
  FIELD           AT 12,0   LEN 8    PROT COLOR=CYAN          "Descrip"
  FIELD           AT 12,8   LEN 70   PROT COLOR=BLUE          "- The description for the Frame."
  FIELD           AT 13,0   LEN 8    PROT COLOR=CYAN          "C"
  FIELD           AT 13,8   LEN 70   PROT COLOR=BLUE          "- The color to render the description in."
  FIELD           AT 14,0   LEN 8    PROT COLOR=CYAN          "Welcome"
  FIELD           AT 14,8   LEN 70   PROT COLOR=BLUE          "- A welcome message to display at the top of the screen."
  FIELD           AT 15,0   LEN 8    PROT COLOR=CYAN          "C"
  FIELD           AT 15,8   LEN 70   PROT COLOR=BLUE          "- The color to render the Welcome Message in."
  FIELD           AT 17,0   LEN 78   PROT COLOR=BLUE          "Leave the Welcome Message blank for the default GMMTEXT message."
  FIELD           AT 18,0   LEN 78   PROT COLOR=BLUE          "Leave the Order blank to prevent FSPF from showing it."
  FIELD           AT 20,0   LEN 8    PROT COLOR=CYAN          "PF5"
  FIELD           AT 20,8   LEN 70   PROT COLOR=BLUE          "- Reload without saving."
  FIELD           AT 20,40  LEN 8    PROT COLOR=CYAN          "ENTER"
  FIELD           AT 20,48  LEN 30   PROT COLOR=BLUE          "- Commit changes."
  FIELD           AT 21,0   LEN 8    PROT COLOR=CYAN          "PF4"
  FIELD           AT 21,8   LEN 70   PROT COLOR=BLUE          "- Edit the Links."
  FIELD           AT 23,0   LEN 78   PROT COLOR=BLUE          "Press ENTER to continue to the next page."

  CURSOR          AT 23,0
ENDMAP * EDITFRAMEHELP1

MAP EDITFRAMEHELP2 SIZE 24x80
  FIELD           AT 0 ,0   LEN 21  PROT BRIGHT COLOR=BLUE  "FSPF - Frame Editor -"
  FIELD           AT 0 ,22  LEN 18  PROT BRIGHT COLOR=RED   "HELP!"
  FIELD           AT 1 ,0   LEN 78  PROT COLOR=BLUE         "D to Duplicate / P to Purge / ENTER=COMMIT"
  FIELD           AT 1 ,71  LEN 7   PROT COLOR=WHITE        "Rows: 2"

  FIELD           AT 2 ,0   LEN 1   PROT COLOR=CYAN         "A  ID C  Order  Name  Description          C  Welcome Message                C"

  INPUT ACTN1     AT 3 ,0   LEN 1   UNDERSCORE COLOR=YELLOW
  INPUT ID1       AT 3 ,3   LEN 2   UNDERSCORE COLOR=GREEN
  INPUT IDC1      AT 3 ,6   LEN 1   UNDERSCORE COLOR=GREEN
  INPUT ORDER1    AT 3 ,10  LEN 4   NUMERIC UNDERSCORE COLOR=GREEN
  INPUT NAME1     AT 3 ,16  LEN 5   UNDERSCORE COLOR=GREEN
  INPUT DESCR1    AT 3 ,22  LEN 20  UNDERSCORE COLOR=GREEN
  INPUT DESCRC1   AT 3 ,43  LEN 1   UNDERSCORE COLOR=GREEN
  INPUT WELCOM1   AT 3 ,46  LEN 30  UNDERSCORE COLOR=GREEN
  INPUT WELCOMC1  AT 3 ,77  LEN 1   UNDERSCORE COLOR=GREEN

  STOP            AT 3 ,2
  STOP            AT 3 ,8
  STOP            AT 3 ,15
  STOP            AT 3 ,21
  STOP            AT 3 ,45
  STOP            AT 3 ,79

  FIELD           AT 6 ,0   LEN 78   PROT COLOR=BLUE          "Creating Frames is completely optional."
  FIELD           AT 7 ,0   LEN 78   PROT COLOR=BLUE          "They only exist for FSPF to list in the lower right."
  FIELD           AT 9 ,0   LEN 78   PROT COLOR=BLUE          "Name is the the only required field, and it must be unique."
  FIELD           AT 11,0   LEN 78   PROT COLOR=BLUE          "If Order is left blank FSPF will not list the Frame."
  FIELD           AT 13,0   LEN 78   PROT COLOR=BLUE          "The Welcome Message is displayed on the second line when the Frame is active."
  FIELD           AT 15,0   LEN 78   PROT COLOR=BLUE          "The default Frame when FSPF starts is MAIN."
  FIELD           AT 17,0   LEN 78   PROT COLOR=BLUE          "Unless overridden 'M' and 'MAIN' will always jump to the Frame MAIN."

  FIELD           AT 23,0   LEN 78   PROT COLOR=BLUE          "Press ENTER to exit."

  CURSOR          AT 23,0
ENDMAP * EDITFRAMEHELP2

