MAP BRICKSHELPHELP SIZE 24x80
  FIELD           AT 0 ,0   LEN 9    PROT BRIGHT COLOR=CYAN   "FSPF HELP"
  FIELD           AT 0 ,10  LEN 12   PROT BRIGHT COLOR=GREEN  "Help for HELP"
  FIELD           AT 0 ,60  LEN 10   PROT COLOR=RED           "ADMIN ONLY"
  FIELD           AT 0 ,72  LEN 5    PROT BRIGHT COLOR=PINK   "?HELP"
  
  FIELD           AT 2 ,28  LEN 19   PROT COLOR=BLUE          "Help for FSPF HELP!"

  FIELD           AT 1 ,1   LEN 1    PROT COLOR=CYAN          "\"
  FIELD           AT 2 ,2   LEN 1    PROT COLOR=CYAN          "\"
  FIELD           AT 3 ,3   LEN 1    PROT COLOR=CYAN          "\"
  FIELD           AT 4 ,4   LEN 1    PROT COLOR=CYAN          "\"
  FIELD           AT 5 ,5   LEN 1    PROT COLOR=CYAN          "\"
  FIELD           AT 6 ,6   LEN 1    PROT COLOR=CYAN          "=> Help topic or command."

  FIELD           AT 1 ,11  LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 2 ,12  LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 3 ,13  LEN 1    PROT COLOR=GREEN         "\"
  FIELD           AT 4 ,14  LEN 1    PROT COLOR=GREEN         "=> Brief note on the help topic."

  FIELD           AT 1 ,68  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 2 ,67  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 3 ,66  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 4 ,65  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 5 ,64  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 6 ,63  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 7 ,62  LEN 1    PROT COLOR=RED           "/"
  FIELD           AT 8 ,13  LEN 49   PROT COLOR=RED           "Some things are only for Admins or Developers. <="

  FIELD           AT 1 ,75  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 2 ,74  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 3 ,73  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 4 ,72  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 5 ,71  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 6 ,70  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 7 ,69  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 8 ,68  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 9 ,67  LEN 1    PROT COLOR=PINK          "/"
  FIELD           AT 10,20  LEN 47   PROT COLOR=PINK          "How to get to this Help screen. (Type this!) <="

  FIELD           AT 12,15  LEN 19   PROT COLOR=WHITE         "Help via the ? prefix is always available."
  FIELD           AT 13,15  LEN 19   PROT COLOR=WHITE         "?HELP will always bring you to this screen."
  FIELD           AT 14,15  LEN 19   PROT COLOR=WHITE         "@HELP will always bring you to the HELP Frame."

  FIELD           AT 16,4   LEN 1    PROT COLOR=YELLOW       "=> When available, a link for more information is provided."
  FIELD           AT 17,7   LEN 1    PROT COLOR=YELLOW       "Space permitting. Visit the README if no link is present."
  FIELD           AT 18,7   LEN 1    PROT COLOR=YELLOW       "READ THE DOCS!!! They are very detailed and super helpful."
  FIELD           AT 17,3   LEN 1    PROT COLOR=YELLOW       "/"
  FIELD           AT 18,2   LEN 1    PROT COLOR=YELLOW       "/"
  FIELD           AT 19,1   LEN 1    PROT COLOR=YELLOW       "/"

  FIELD           AT 20,0   LEN 70   PROT COLOR=BLUE          "More information can be found in the BRICKS_TS GitHub repository:"
