MAP BRICKSHELPQWCS SIZE 24x80
  FIELD           AT 0 ,0   LEN 15   PROT BRIGHT COLOR=CYAN   "Quick Reference"
  FIELD           AT 0 ,16  LEN 12   PROT BRIGHT COLOR=GREEN  "EXEC CICS WEB — client side"
  FIELD           AT 0 ,72  LEN 5    PROT BRIGHT COLOR=PINK   "?QWCS"
  
  FIELD           AT 2 ,0   LEN 7    PROT COLOR=CYAN          "Command"
  FIELD           AT 2 ,50  LEN 7    PROT COLOR=CYAN          "Purpose"

  FIELD           AT 3 ,0   LEN 40   PROT COLOR=BLUE          "OPEN HOST(s) SESSTOKEN(v) [PORT(n)] [SCHEME(s)]"
  FIELD           AT 3 ,50  LEN 30   PROT COLOR=BLUE          "Open client session."

  FIELD           AT 4 ,0   LEN 40   PROT COLOR=WHITE         "CONVERSE     SESSTOKEN(t) METHOD(m) PATH(p)"
  FIELD           AT 5 ,13  LEN 40   PROT COLOR=WHITE         "[FROM(b)] INTO(v) [STATUSCODE(v)]"
  FIELD           AT 4 ,50  LEN 30   PROT COLOR=WHITE         "One-shot send + receive."
  FIELD           AT 6 ,0   LEN 40   PROT COLOR=BLUE          "SEND         SESSTOKEN(t) METHOD(m) PATH(p) "
  FIELD           AT 7 ,13  LEN 40   PROT COLOR=BLUE          "[FROM(b)] [QUERYSTRING(s)] [MEDIATYPE(s)]"
  FIELD           AT 6 ,50  LEN 30   PROT COLOR=BLUE          "Stage request."
  FIELD           AT 8 ,0   LEN 40   PROT COLOR=WHITE         "RECEIVE      SESSTOKEN(t) INTO(v) [STATUSCODE(v)]"
  FIELD           AT 9 ,13  LEN 40   PROT COLOR=WHITE         "[MEDIATYPE(v)] [MAXLENGTH(n)]"
  FIELD           AT 8 ,50  LEN 30   PROT COLOR=WHITE         "Fire staged request."
  FIELD           AT 10,0   LEN 40   PROT COLOR=BLUE          "CLOSE        SESSTOKEN(t)"
  FIELD           AT 10,50  LEN 30   PROT COLOR=BLUE          "Release session."
  FIELD           AT 11,0   LEN 40   PROT COLOR=WHITE         "CONVERSE WEB ..."
  FIELD           AT 11,50  LEN 30   PROT COLOR=WHITE         "Alias for WEB CONVERSE."

  FIELD           AT 12,0   LEN 40   PROT COLOR=BLUE          "OPEN  URIMAP(name) SESSTOKEN(v)"
  FIELD           AT 12,50  LEN 30   PROT COLOR=BLUE          "Open via URIMAP."
  FIELD           AT 13,0   LEN 40   PROT COLOR=WHITE         "SEND  URIMAP(name) METHOD(m) PATH(p) ... INTO(v)"
  FIELD           AT 13,50  LEN 30   PROT COLOR=WHITE         "One-shot via URIMAP."

  FIELD           AT 14,0   LEN 40   PROT COLOR=BLUE          "WRITE HTTPHEADER(name) VALUE(v) SESSTOKEN(t)"
  FIELD           AT 14,50  LEN 30   PROT COLOR=BLUE          "Set outbound request header."
  FIELD           AT 15,0   LEN 40   PROT COLOR=WHITE         "READ  HTTPHEADER(name) VALUE(v) SESSTOKEN(t)"
  FIELD           AT 16,6   LEN 40   PROT COLOR=WHITE         "[LENGTH(v)]"
  FIELD           AT 15,50  LEN 30   PROT COLOR=WHITE         "Read response header."

  FIELD           AT 17,0   LEN 40   PROT COLOR=BLUE          "STARTBROWSE / READNEXT / ENDBROWSE HTTPHEADER"
  FIELD           AT 18,35  LEN 40   PROT COLOR=BLUE          "SESSTOKEN(t)"
  FIELD           AT 17,50  LEN 30   PROT COLOR=BLUE          "Walk response headers."
  FIELD           AT 19,0   LEN 40   PROT COLOR=WHITE         "EXTRACT SESSTOKEN(t) [SCHEME(v)] [HOST(v)]"
  FIELD           AT 20,21  LEN 40   PROT COLOR=WHITE         "[PORT(v)]   [PATH(v)]"
  FIELD           AT 19,50  LEN 30   PROT COLOR=WHITE         "Inspect session endpoint."
  FIELD           AT 21,0   LEN 40   PROT COLOR=BLUE          "EXTRACT URIMAP(name) [SCHEME(v)] [HOST(v)]"
  FIELD           AT 22,21  LEN 40   PROT COLOR=BLUE          "[PORT(v)]   [PATH(v)]"
  FIELD           AT 21,50  LEN 30   PROT COLOR=BLUE          "Inspect URIMAP entry."

  FIELD           AT 23,0   LEN 70   PROT COLOR=BLUE          "Press ENTER to exit."

  CURSOR          AT 23,0
ENDMAP * BRICKSHELPQWCS

MAP BRICKSHELPQDOC SIZE 24x80
  FIELD           AT 0 ,0   LEN 15   PROT BRIGHT COLOR=CYAN   "Quick Reference"
  FIELD           AT 0 ,16  LEN 12   PROT BRIGHT COLOR=GREEN  "EXEC CICS DOCUMENT - Chunked Body Builder"
  FIELD           AT 0 ,72  LEN 5    PROT BRIGHT COLOR=PINK   "?QDOC"
  
  FIELD           AT 2 ,0   LEN 7    PROT COLOR=CYAN          "Command"
  FIELD           AT 2 ,18  LEN 7    PROT COLOR=CYAN          "Options"
  FIELD           AT 2 ,50  LEN 7    PROT COLOR=CYAN          "Purpose"

  FIELD           AT 3 ,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT CREATE"
  FIELD           AT 3 ,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(v) [SYMBOLLIST(s)"
  FIELD           AT 4 ,30  LEN 30   PROT COLOR=BLUE          "[LISTLENGTH(n)]]"
  FIELD           AT 5 ,30  LEN 30   PROT COLOR=BLUE          "[DELIMITER(s)]"
  FIELD           AT 3 ,50  LEN 30   PROT COLOR=GREEN         "New empty document."
  FIELD           AT 7 ,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT INSERT"
  FIELD           AT 7 ,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t) FROM(b) [LENGTH(n)] [AT(pos)]"
  FIELD           AT 7 ,50  LEN 30   PROT COLOR=GREEN         "Append / splice bytes."
  FIELD           AT 8 ,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT INSERT"
  FIELD           AT 8 ,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t) SYMBOL(name)"
  FIELD           AT 8 ,50  LEN 30   PROT COLOR=GREEN         "Substitute from symbol list."
  FIELD           AT 9 ,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT INSERT"
  FIELD           AT 9 ,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t) DOCUMENT(other-tok)"
  FIELD           AT 10 ,30  LEN 30   PROT COLOR=BLUE          "[AT(pos)]"
  FIELD           AT 9 ,50  LEN 30   PROT COLOR=GREEN         "Splice another document."
  FIELD           AT 12,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT SET"
  FIELD           AT 12,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t) SYMBOLLIST(s)"
  FIELD           AT 13,30  LEN 30   PROT COLOR=BLUE          "[DELIMITER(d)]"
  FIELD           AT 12,50  LEN 30   PROT COLOR=GREEN         "Re-bind symbol list."
  FIELD           AT 14,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT RETRIEVE"
  FIELD           AT 14,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t) INTO(b) LENGTH(v)"
  FIELD           AT 14,50  LEN 30   PROT COLOR=GREEN         "Read assembled body."
  FIELD           AT 15,0   LEN 40   PROT COLOR=WHITE         "DOCUMENT DELETE"
  FIELD           AT 15,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t)"
  FIELD           AT 15,50  LEN 30   PROT COLOR=GREEN         "Release document."
  FIELD           AT 17,0   LEN 40   PROT COLOR=WHITE         "WEB SEND"
  FIELD           AT 17,18  LEN 30   PROT COLOR=BLUE          "DOCTOKEN(t) [STATUSCODE(n)]"
  FIELD           AT 18,30  LEN 30   PROT COLOR=BLUE          "[MEDIATYPE(s)]"
  FIELD           AT 17,50  LEN 30   PROT COLOR=GREEN         "Emit document as response."

  FIELD           AT 20,0   LEN 70   PROT COLOR=BLUE          "The online manual can be found in the BRICKS_TS GitHub repository:"
  FIELD           AT 21,0   LEN 70   PROT COLOR=YELLOW        "https://github.com/moshix/BRICKS_TS/blob/main/PROGRAMMING.md"

  FIELD           AT 23,0   LEN 70   PROT COLOR=BLUE          "Press ENTER to exit."

  CURSOR          AT 23,0
ENDMAP * BRICKSHELPQDOC

