MAP BRICKSHELPLOGO SIZE 24x80
  FIELD           AT 0 ,0   LEN 15   PROT BRIGHT COLOR=CYAN   "Quick Reference"
  FIELD           AT 0 ,16  LEN 12   PROT BRIGHT COLOR=GREEN  "Logging on and off of Bricks"
  FIELD           AT 0 ,72  LEN 5    PROT BRIGHT COLOR=PINK   "?LOGO"
  
  FIELD           AT 2 ,0   LEN 70   PROT COLOR=CYAN          "LOGON:"
  FIELD           AT 3 ,0   LEN 70   PROT COLOR=BLUE          "Use the command CSSN to logon to Bricks."
  FIELD           AT 4 ,0   LEN 70   PROT COLOR=BLUE          "You will be prompted for your Userid and Password."
  FIELD           AT 6 ,0   LEN 70   PROT COLOR=WHITE         "CSSN LOGON"
  FIELD           AT 6 ,25  LEN 40   PROT COLOR=GREEN         "Logon to Bricks"
  FIELD           AT 7 ,0   LEN 70   PROT COLOR=WHITE         "CSSN"
  FIELD           AT 7 ,25  LEN 40   PROT COLOR=GREEN         "The LOGON option is optional."

  FIELD           AT 9 ,0   LEN 70   PROT COLOR=CYAN          "LOGOFF:"
  FIELD           AT 10,0   LEN 70   PROT COLOR=BLUE          "Use the command CSSF to logoff of Bricks."
  FIELD           AT 12,0   LEN 70   PROT COLOR=WHITE         "CSSF LOGOFF"
  FIELD           AT 12,25  LEN 40   PROT COLOR=GREEN         "Logoff of Bricks and stay connected."
  FIELD           AT 13,0   LEN 70   PROT COLOR=WHITE         "CSSF DISC / GOODNIGHT"
  FIELD           AT 13,25  LEN 40   PROT COLOR=GREEN         "Logoff of Bricks and disconnect."
  FIELD           AT 14,0   LEN 70   PROT COLOR=BLUE          "(The option for CSSF is required.)"
  
  FIELD           AT 16,0   LEN 12   PROT COLOR=CYAN          "Please note:"
  FIELD           AT 16,13  LEN 7    PROT COLOR=BLUE          "Neither"
  FIELD           AT 16,19  LEN 4    PROT COLOR=WHITE         "CSSN"
  FIELD           AT 16,24  LEN 3    PROT COLOR=BLUE          "nor"
  FIELD           AT 16,28  LEN 4    PROT COLOR=WHITE         "CSSF"
  FIELD           AT 16,33  LEN 14   PROT COLOR=BLUE          "will work from"
  FIELD           AT 16,48  LEN 4    PROT COLOR=WHITE         "FSPF"
  FIELD           AT 17,0   LEN 70   PROT COLOR=BLUE          "You may only logon or logoff from the blank command line."
  FIELD           AT 18,0   LEN 70   PROT COLOR=BLUE          "Most of the demos will work while unauthenticated."

  FIELD           AT 20,0   LEN 70   PROT COLOR=BLUE          "The online manual can be found in the BRICKS_TS GitHub repository:"
  FIELD           AT 21,0   LEN 70   PROT COLOR=YELLOW        "https://github.com/moshix/bricks_ts#readme"

  FIELD           AT 23,0   LEN 70   PROT COLOR=BLUE          "Press ENTER to exit."

  CURSOR          AT 23,0
ENDMAP * BRICKSHELPLOGO

