MAP DEBUGCONSOLE SIZE 24x80
  FIELD           AT 0 ,0   LEN 18  PROT COLOR=YELLOW         "FSPF Debug Console"
  FIELD FIND_TEXT AT 0 ,28  LEN 30  PROT COLOR=WHITE
  FIELD           AT 0 ,20  LEN 7   PROT BRIGHT COLOR=CYAN    "Search:"
  FIELD FIND_CNT  AT 0 ,54  LEN 4   PROT COLOR=WHITE
  FIELD           AT 0 ,47  LEN 6   PROT BRIGHT COLOR=CYAN    "Found:"
  FIELD CUR_PAGE  AT 0 ,65  LEN 4   PROT COLOR=WHITE
  FIELD           AT 0 ,59  LEN 5   PROT BRIGHT COLOR=CYAN    "Page:"
  FIELD PAGE_CNT  AT 0 ,74  LEN 4   PROT COLOR=WHITE
  FIELD           AT 0 ,70  LEN 4   PROT BRIGHT COLOR=CYAN    "Of:"

  FIELD OUTPUT1    AT 1 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT2    AT 2 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT3    AT 3 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT4    AT 4 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT5    AT 5 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT6    AT 6 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT7    AT 7 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT8    AT 8 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT9    AT 9 ,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT10   AT 10,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT11   AT 11,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT12   AT 12,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT13   AT 13,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT14   AT 14,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT15   AT 15,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT16   AT 16,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT17   AT 17,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT18   AT 18,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT19   AT 19,0   LEN 78  PROT UNDERSCORE COLOR=BLUE
  FIELD OUTPUT20   AT 20,0   LEN 78  PROT UNDERSCORE COLOR=BLUE

  FIELD           AT 21,0   LEN 11  PROT                      "Command ==>"
  INPUT OPTION    AT 21,12  LEN 60  UNDERSCORE COLOR=CYAN
