  INPUT MSG       AT 22,0   LEN 79  PROT BRIGHT COLOR=RED
  FIELD           AT 23,0   LEN 78  PROT COLOR=BLUE         "PF1=Help  PF2=Find  PF3=Exit  PF5=Reload  PF7/8=Up/Down  PF6/9=Top/Bottom"
  CURSOR          AT OPTION

ENDMAP * DEBUGCONSOLE
